const catalogHash = (value: object): string => createHash('sha256').update(JSON.stringify(value), 'utf8').digest('hex');

it.each(pinnedCatalogs)('$name keeps its approved canonical JSON hash', ({ value, hash }) => {
  expect(catalogHash(value)).toBe(hash);
});

it('detects a changed value in a cloned catalog using the pinned catalog hash', () => {
  const changed = structuredClone(TRIAL_BUILDINGS);
  changed.hospital.upkeepMilli += 1;
  expect(catalogHash(changed)).not.toBe(pinnedCatalogs[0].hash);
});

it('pins ITEM_CATALOG for P6-A', async () => {
  const { ITEM_CATALOG }=await import('../trial/items.js');
  expect(catalogHash(ITEM_CATALOG)).toBe('7fdeadb141aba95586555f531e044fcdc8a5eccd2c2766fab94c48714793f96d');
});
it('pins ITEM_TRIAL for P6-A', async () => {
  const { ITEM_TRIAL }=await import('../trial/items.js');
  expect(catalogHash(ITEM_TRIAL)).toBe('fcdbbc87ed52f6df25246e044b25e3c6acbd56de98360f31b7a16ec4a3b5e198');
});
it.each([
  { name: 'NPC_ORIGINS', value: NPC_ORIGINS, hash: 'c252b2c5d31d302c307df967c94b43714f4e3debd527299819f60117f0378f09' },
  { name: 'NPC_HOBBIES', value: NPC_HOBBIES, hash: '8a4c0e75fca9aa9b8fd5e26a5bfac38aa161864e02b97832c77955089d7205c2' },
  { name: 'P7A_TRIAL', value: P7A_TRIAL, hash: 'b1429bf557d9a96e825a2d9a6d788524ee1e57db1572d35a6c405f2924797013' },
])('$name keeps the P7-A canonical JSON hash', ({ value, hash }) => {
  expect(catalogHash(value)).toBe(hash);
});

